import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Remove near-duplicates based on correlation
    keep = []
    correlated = set()
    for i, fid1 in enumerate(feats.ids):
        if fid1 in correlated:
            continue
        keep.append(i)
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if fid2 in correlated:
                continue
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                correlated.add(fid2)

    # Filter to non-duplicate features
    ids_keep = [feats.ids[i] for i in keep]
    x_keep = feats.x[:, keep]

    # Calculate effect sizes (mean difference)
    effect_sizes = []
    for i, fid in enumerate(ids_keep):
        y1 = feats.y[feats.x[:, i] > np.mean(feats.x[:, i])]
        y0 = feats.y[feats.x[:, i] <= np.mean(feats.x[:, i])]
        if len(y1) > 0 and len(y0) > 0:
            effect = np.mean(y1) - np.mean(y0)
        else:
            effect = 0
        effect_sizes.append(abs(effect))

    # Sort by effect size and limit to MAX_DRIVERS-1 (at most 4)
    sorted_indices = np.argsort(effect_sizes)[::-1][:MAX_DRIVERS-1]
    drivers = tuple([ids_keep[i] for i in sorted_indices if effect_sizes[i] > 0])

    # If no drivers found, return empty
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select features for regression (top 20)
    top_features = np.argsort(effect_sizes)[::-1][:20]
    columns = tuple([ids_keep[i] for i in top_features])

    # Check for interactions (product terms)
    products = []
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            if abs(np.corrcoef(x_keep[:, top_features[i]], x_keep[:, top_features[j]])[0,1]) > 0.6:
                products.append((ids_keep[top_features[i]], ids_keep[top_features[j]]))

    # Create weighted score (simple sum of top features)
    loadings = {}
    for i, fid in enumerate(columns):
        loadings[fid] = effect_sizes[ids_keep.index(fid)]

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
